    @Test fun the_olaya_point_lies_in_the_olaya_district_not_its_municipality() {
        val districts = CityIndex.parseDistricts(body)
        assertEquals(4, districts.size)
        val d = CityIndex.districtAround(districts, 24.693086, 46.684508)
        assertNotNull(d)
        assertEquals(10, d!!.level)
        assertTrue(d.name, d.name.contains("العليا"))
        assertTrue(d.ring.size in 3..60)
    }

    @Test fun a_timed_out_server_is_no_answer_not_an_empty_city() {
        assertTrue(CityIndex.overpassGaveUp("""{"elements":[],"remark":"runtime error: Query timed out in \"query\" at line 1 after 26 seconds."}"""))
        assertTrue(CityIndex.overpassGaveUp("<html>busy</html>"))
        assertTrue(!CityIndex.overpassGaveUp("""{"elements":[]}"""))
    }

    @Test fun stored_districts_round_trip_and_a_point_outside_all_finds_none() {
        val districts = CityIndex.parseDistricts(body)
        val back = CityIndex.decodeDistricts(CityIndex.encodeDistricts("الرياض", 1_000L, districts))!!
        assertEquals("الرياض", back.first)
        assertEquals(districts.size, back.third.size)
        assertEquals(districts.map { it.name }, back.third.map { it.name })
        assertNull(CityIndex.districtAround(back.third, 21.5, 39.2))
        assertTrue(CityIndex.districtsQuery(GeoBox(24.45, 46.45, 25.05, 47.05)).contains("(24.45,46.45,25.05,47.05)"))
    }
